// # inverse: nothing here lends loop-local storage past the loop
// def inverse_section(p: B) -> None:
//     outer = B(7)
//     holder = Rec(0)
//     total = 0
//     for i in range(3):
//         b = B(i)
//         holder = outer.rec_m()  # tpyc: ok
//         holder = first(p)  # tpyc: ok
//         holder = b.own_m()  # tpyc: ok
//         total += b.val_m()  # tpyc: ok
//         inner = b.rec_m()  # tpyc: ok
//         inner.x += 1
//         total += inner.x
//     holder.x += 100
//     print("inverse:", holder.x, total)
void inverse_section(B& p) {
    std::optional<Rec> __slot_2;
    B outer = B(7);
    Rec __slot_1 = Rec(0);
    Rec* holder = &__slot_1;
    int32_t total = 0;
    for (int32_t i = 0; i < 3; ++i) {
        B b = B(i);
        holder = &(outer.rec_m());
        holder = &(::tpyapp::main::first(p));
        holder = &*(__slot_2 = b.own_m());
        total = ::tpy::add_check<int32_t>(total, b.val_m());
        Rec& inner = b.rec_m();
        inner.x = ::tpy::add_check<int32_t>(inner.x, 1);
        total = ::tpy::add_check<int32_t>(total, inner.x);
    }
    holder->x = ::tpy::add_check<int32_t>(holder->x, 100);
    std::cout << "inverse:" << " " << holder->x << " " << total << "\n" << ::tpy::check_signals;
}

